type Env = Readonly<Record<string, string | undefined>>;

function loadConfig(env: Env): { nodeEnv: string; tokenSecret: string } {
  const problems: string[] = [];
  const tokenSecret = env["TOKEN_SECRET"] ?? "";
  if (tokenSecret.length < 32) problems.push("TOKEN_SECRET too short");
  const nodeEnv = env["NODE_ENV"] ?? "development";
  if (!["development", "test", "production"].includes(nodeEnv)) problems.push("bad NODE_ENV");
  if (problems.length > 0) throw new Error(problems.join("; "));
  return { nodeEnv, tokenSecret };
}

for (const env of [{ TOKEN_SECRET: "x".repeat(32) }, { NODE_ENV: "prod", TOKEN_SECRET: "abc" }]) {
  try {
    console.log(loadConfig(env).nodeEnv);
  } catch (error) {
    console.log(error instanceof Error ? error.message : error);
  }
}

