class StrictEmitter<Events extends { [K in keyof Events]: unknown[] }> {
  private readonly listeners: { [K in keyof Events]?: ((...args: Events[K]) => void)[] } = {};

  on<K extends keyof Events>(name: K, listener: (...args: Events[K]) => void): this {
    (this.listeners[name] ??= []).push(listener);
    return this;
  }

  emit<K extends keyof Events>(name: K, ...args: Events[K]): boolean {
    const list = this.listeners[name] ?? [];
    for (const listener of list) listener(...args);
    return list.length > 0;
  }
}

